function furi(root=document.body){const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let nodes=[];while(w.nextNode()){let n=w.currentNode,p=n.parentElement;if(p&&!p.closest('.music-gallery-list')&&!p.closest('#abyssShardHud')&&!['SCRIPT','STYLE','RT','RUBY'].includes(p.tagName)){if(furiChecked.get(n)===n.data)continue;if(n.data.includes('遺物'))n.data=n.data.replaceAll('遺物','レリック');furiChecked.set(n,n.data);if(keys.some(k=>n.data.includes(k)))nodes.push(n)}}for(const n of nodes){let s=n.data,rx=new RegExp('('+keys.filter(k=>s.includes(k)).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','g');if(rx.source==='()')continue;let t=document.createElement('template');let marked=s.replace(rx,(m,_,offset)=>{if(m.length===1&&(/[一-龯々]/.test(s[offset-1]||'')||/[一-龯々]/.test(s[offset+1]||'')))return m;return `<ruby>${m}<rt>${READINGS[m]}</rt></ruby>`});if(marked!==s){t.innerHTML=marked;n.replaceWith(t.content)}}}
let audio=null,bgm=null,sfxBus=null,bgmDuckUntil=0,muted=false,mode='map1',step=0,galleryOpen=false,hiddenPaused=false,rewardWasOpen=false;
const volumeGain=value=>Math.max(0,Math.min(1,Number(value)||0));
